export function getTemplateDef(key: string): EmailTemplateDef | undefined {
  return EMAIL_TEMPLATES.find((t) => t.key === key);
}

/** Every variable a template may use (its own plus the common ones). */
export function templateVariables(def: EmailTemplateDef): TemplateVariable[] {
  return [...COMMON_VARIABLES, ...def.variables];
}

export const isEmailLocale = (v: unknown): v is EmailLocale =>
  typeof v === 'string' && (EMAIL_LOCALES as readonly string[]).includes(v);
